mapper.select:
SELECT u.user_id AS db_key, u.user_id, u.mem_cd, mc.code_nm AS mem_cd_nm, u.nickname, u.gen_cd, CONVERT_FROM(DECRYPT(DECODE(u.user_nm,'HEX'),#{encKey}::BYTEA,'AES'),'UTF8') AS user_nm, CONVERT_FROM(DECRYPT(DECODE(u.phone,'HEX'),#{encKey}::BYTEA,'AES'),'UTF8') AS phone, CONVERT_FROM(DECRYPT(DECODE(u.email,'HEX'),#{encKey}::BYTEA,'AES'),'UTF8') AS email, CONVERT_FROM(DECRYPT(DECODE(u.birth,'HEX'),#{encKey}::BYTEA,'AES'),'UTF8') AS birth, u.status_cd, sc.code_nm AS status_cd_nm, u.use_yn FROM t_user u LEFT JOIN t_code mc ON mc.code_id = u.mem_cd AND mc.p_code_id = 'MEM00' LEFT JOIN t_code sc ON sc.code_id = u.status_cd AND sc.p_code_id = 'STATUS00' WHERE u.use_yn = 'Y' AND u.mem_cd = #{memCd} AND u.status_cd = #{statusCd}
AND (u.user_id LIKE '%' || #{searchKeyword} || '%' OR CONVERT_FROM(DECRYPT(DECODE(u.user_nm,'HEX'),#{encKey}::BYTEA,'AES'),'UTF8') LIKE '%' || #{searchKeyword} || '%')
ORDER BY u.reg_dt DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM t_user WHERE use_yn = 'Y'
AND mem_cd = #{memCd}
AND status_cd = #{statusCd}

    AND (user_id LIKE '%' || #{searchKeyword} || '%'
         OR CONVERT_FROM(DECRYPT(DECODE(user_nm,'HEX'),#{encKey}::BYTEA,'AES'),'UTF8') LIKE '%' || #{searchKeyword} || '%')

mapper.update:
UPDATE t_user SET
    user_pw = #{userPw}, last_upd_dt = NOW(),
    pw_expire_dt = NOW() + (COALESCE((SELECT pw_expire_cnt FROM t_config LIMIT 1), 90) * INTERVAL '1 day'),
    upd_id = #{updId}, upd_dt = NOW(), upd_ip = #{updIp}
WHERE user_id = #{dbKey}

UPDATE t_user
   SET status_cd = #{statusCd},
       fail_cnt = CASE WHEN #{statusCd} = 'STATUS01' THEN 0 ELSE fail_cnt END,
       is_account_non_locked_ti = CASE WHEN #{statusCd} = 'STATUS01' THEN NULL ELSE is_account_non_locked_ti END,
       upd_id = #{updId}, upd_dt = NOW(), upd_ip = #{updIp}
 WHERE user_id = #{userId}

UPDATE t_user SET
    pw_expire_dt = NOW() + (COALESCE((SELECT pw_expire_cnt FROM t_config LIMIT 1), 90) * INTERVAL '1 day'),
    upd_id = #{updId}, upd_dt = NOW(), upd_ip = #{updIp}
WHERE user_id = #{userId}
